import boto3


def get_vision_client(region):
    return boto3.client("rekognition", region_name=region)


def get_translate_client(region):
    return boto3.client("translate", region_name=region)

def normalize_label_response(response):
    return [{"name": label["Name"], "confidence": label["Confidence"] / 100.0} for label in response["Labels"]]


def normalize_text_response(response):
    return [text_detection["DetectedText"] for text_detection in response["TextDetections"]]


def normalize_safety_response(response):
    return response["ModerationLabels"][0]["Confidence"] / 100.0 if response["ModerationLabels"] else None

import boto3


def image_summary(payload, config=None):
    config = config or {}
    client = boto3.client("rekognition", region_name=config.get("region"))
    labels_response = client.detect_labels(
        Image={"Bytes": payload["image_bytes"]},
        MaxLabels=int(config.get("max_labels", 10)),
    )
    text_response = client.detect_text(
        Image={"Bytes": payload["image_bytes"]},
    )
    labels = [label["Name"] for label in labels_response["Labels"]]
    text = [text_detection["DetectedText"] for text_detection in text_response["TextDetections"]]
    return {"summary": f"Labels: {labels}, Text: {text}"}

import boto3


def alt_text_translate(text, source_lang, target_lang, config=None):
    config = config or {}
    client = boto3.client("translate", region_name=config.get("region"))
    response = client.translate_text(
        Text=text,
        SourceLanguageCode=source_lang,
        TargetLanguageCode=target_lang,
    )
    return response["TranslatedText"]

import boto3


def visual_safety_text(text, config=None):
    config = config or {}
    client = boto3.client("comprehend", region_name=config.get("region"))
    response = client.detect_sentiment(
        Text=text,
        LanguageCode="en",
    )
    return response["Sentiment"] == "NEGATIVE"

import boto3


def image_asset_archive(image_bytes, caption, config=None):
    config = config or {}
    client = boto3.client("s3", region_name=config.get("region"))
    client.put_object(
        Bucket=config.get("bucket"),
        Key=f"images/{caption}.jpg",
        Body=image_bytes,
    )
